/*
 * Microsoft.UI.Input.dll's common pieces: the Windows App SDK's lifted
 * content, input and windowing classes (Microsoft.UI.Content,
 * Microsoft.UI.Input, Microsoft.UI.Windowing), as NovaOS serves them to
 * Microsoft's XAML framework (roadmap 32.4).  See dll.cpp for what is here.
 *
 * Every object derives from Object (its reference count, its heap) and
 * from Stub<I> for each interface it implements (stubs.h, generated by
 * build.py: every method has a default, so a class overrides only what it
 * does).  LIFTED_OBJECT gives a class its IUnknown and IInspectable;
 * its QueryInterface lists its interfaces through lifted_qi.
 */
#pragma once
#define W(s) ((const WCHAR *)(s))
#ifndef RO_E_CLOSED
#define RO_E_CLOSED ((HRESULT)0x80000013L)
#endif
#ifndef E_ILLEGAL_METHOD_CALL
#define E_ILLEGAL_METHOD_CALL ((HRESULT)0x8000000EL)
#endif
