/* the heap every object of this DLL lives on */
struct Object
{
    LONG m_refs = 1;
    virtual ~Object() {}
    static void *operator new(size_t n) { return HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, n); }
    static void operator delete(void *p) { HeapFree(GetProcessHeap(), 0, p); }
};

/* a class's IUnknown (AddRef, Release) and IInspectable (its runtime class
 * name); QueryInterface is the class's own */
#define LIFTED_OBJECT(NAME)                                                                             \
    ULONG STDMETHODCALLTYPE AddRef() override { return (ULONG)InterlockedIncrement(&m_refs); }          \
    ULONG STDMETHODCALLTYPE Release() override                                                          \
    {                                                                                                   \
        LONG r = InterlockedDecrement(&m_refs);                                                         \
        if (!r) delete this;                                                                            \
        return (ULONG)r;                                                                                \
    }                                                                                                   \
    HRESULT STDMETHODCALLTYPE GetIids(ULONG *n, IID **iids) override { *n = 0; *iids = nullptr; return S_OK; } \
    HRESULT STDMETHODCALLTYPE GetRuntimeClassName(HSTRING *name) override                              \
    {                                                                                                   \
        return WindowsCreateString(W(NAME), (UINT32)(sizeof(NAME) / sizeof(wchar_t) - 1), name);                                   \
    }                                                                                                   \
    HRESULT STDMETHODCALLTYPE GetTrustLevel(TrustLevel *t) override { *t = BaseTrust; return S_OK; }

/* QueryInterface over interfaces I...: IUnknown, IInspectable and
 * IAgileObject (every object here is used on its thread, as the SDK's are
 * agile) answer with the first */
template <class T> static bool lifted_qi_one(T *, REFIID, void **) { return false; }
template <class T, class I, class... Rest> static bool lifted_qi_one(T *self, REFIID iid, void **out)
{
    if (iid == __uuidof(I)) {
        *out = static_cast<I *>(self);
        return true;
    }
    return lifted_qi_one<T, Rest...>(self, iid, out);
}
template <class T, class First, class... Rest> static HRESULT lifted_qi(T *self, REFIID iid, void **out)
{
    if (!out) return E_POINTER;
    *out = nullptr;
    static const GUID agile = { 0x94EA2B94, 0xE9CC, 0x49E0, { 0xC0, 0xFF, 0xEE, 0x64, 0xCA, 0x8F, 0x5B, 0x90 } };
    if (iid == __uuidof(IUnknown) || iid == __uuidof(IInspectable) || iid == agile)
        *out = static_cast<First *>(self);
    else if (!lifted_qi_one<T, First, Rest...>(self, iid, out))
        return E_NOINTERFACE;
    static_cast<IUnknown *>(*out)->AddRef();
    return S_OK;
}
#define LIFTED_QI(...) \
    HRESULT STDMETHODCALLTYPE QueryInterface(REFIID iid, void **out) override { return lifted_qi<__VA_ARGS__>(this, iid, out); }

template <class T> static void set_ref(T *&slot, T *value)
{
    if (value) value->AddRef();
    if (slot) slot->Release();
    slot = value;
}
template <class T> static HRESULT copy_out(T *value, T **out)
{
    if (!out) return E_POINTER;
    if (value) value->AddRef();
    *out = value;
    return S_OK;
}

/* an event's handlers: H is the handler interface (an ITypedEventHandler
 * instance or IClosableNotifierHandler); Raise calls each with its
 * arguments, from a copy of the list (so a handler may add or remove) */
template <class H> struct Event
{
    struct Entry { INT64 token; H *handler; };
    Entry *m_list = nullptr;
    UINT32 m_count = 0, m_cap = 0;
    INT64 m_next = 1;

    HRESULT Add(H *handler, EventRegistrationToken *token)
    {
        if (!handler || !token) return E_INVALIDARG;
        if (m_count == m_cap) {
            UINT32 cap = m_cap ? m_cap * 2 : 4;
            Entry *n = (Entry *)HeapAlloc(GetProcessHeap(), 0, cap * sizeof(Entry));
            if (!n) return E_OUTOFMEMORY;
            if (m_list) {
                memcpy(n, m_list, m_count * sizeof(Entry));
                HeapFree(GetProcessHeap(), 0, m_list);
            }
            m_list = n;
            m_cap = cap;
        }
        handler->AddRef();
        m_list[m_count].token = m_next++;
        m_list[m_count].handler = handler;
        token->value = m_list[m_count++].token;
        return S_OK;
    }
    HRESULT Remove(EventRegistrationToken token)
    {
        for (UINT32 i = 0; i < m_count; i++)
            if (m_list[i].token == token.value) {
                H *h = m_list[i].handler;
                memmove(&m_list[i], &m_list[i + 1], (m_count - i - 1) * sizeof(Entry));
                m_count--;
                h->Release();
                break;
            }
        return S_OK;
    }
    bool Empty() const { return m_count == 0; }
    template <class... A> void Raise(A... args)
    {
        UINT32 n = m_count;
        if (!n) return;
        H **copy = (H **)HeapAlloc(GetProcessHeap(), 0, n * sizeof(H *));
        if (!copy) return;
        for (UINT32 i = 0; i < n; i++) {
            copy[i] = m_list[i].handler;
            copy[i]->AddRef();
        }
        for (UINT32 i = 0; i < n; i++) {
            copy[i]->Invoke(args...);
            copy[i]->Release();
        }
        HeapFree(GetProcessHeap(), 0, copy);
    }
    void Clear()
    {
        for (UINT32 i = 0; i < m_count; i++) m_list[i].handler->Release();
        m_count = 0;
    }
    ~Event()
    {
        Clear();
        if (m_list) HeapFree(GetProcessHeap(), 0, m_list);
    }
};

/* the DLL's objects one another reach (content.cpp, input.cpp, windowing.cpp) */
struct Island;
struct SiteBridge;
struct InputSources;

/* content.cpp: an island's input sources (made with the island, served by
 * the input classes' GetForIsland) and its bridge's window, once connected */
