bool inputs_message(InputSources *s, HWND hwnd, UINT msg, WPARAM wp, LPARAM lp, LRESULT *result);
HRESULT input_pointer_source(InputSources *s, ixi::IInputPointerSource **out);
HRESULT input_keyboard_source(InputSources *s, ixi::IInputKeyboardSource **out);
HRESULT input_pretranslate_source(InputSources *s, ixi::IInputPreTranslateKeyboardSource **out);
